/** @module user-mfa-management */

import { getComponentStyles } from '@auth0/universal-components-core';
import * as React from 'react';

import { FactorDeleteModal } from '@/components/auth0/my-account/shared/user-mfa-management/factor-delete/factor-delete-modal';
import { EnrollFactorModal } from '@/components/auth0/my-account/shared/user-mfa-management/factor-enrollment/enroll-factor-modal';
import { MFAEmptyState } from '@/components/auth0/my-account/shared/user-mfa-management/factor-list/empty-state';
import { FactorsList } from '@/components/auth0/my-account/shared/user-mfa-management/factor-list/factors-list';
import { GateKeeper } from '@/components/auth0/shared/gate-keeper/gate-keeper';
import { Header } from '@/components/auth0/shared/header';
import { StyledScope } from '@/components/auth0/shared/styled-scope';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import {
  Card,
  CardHeader,
  CardTitle,
  CardDescription,
  CardAction,
  CardContent,
} from '@/components/ui/card';
import { useUserMFA } from '@/hooks/my-account/use-user-mfa';
import { useTelemetry } from '@/hooks/shared/use-telemetry';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import type {
  UserMFAManagementProps,
  UserMFAManagementViewProps,
} from '@/types/my-account/user-mfa-management/user-mfa-management-types';

const DEFAULT_STYLING: UserMFAManagementProps['styling'] = {
  variables: { common: {}, light: {}, dark: {} },
  classes: {},
};

/**
 * Multi-factor authentication management component.
 *
 * Complete MFA management interface for enrolling, viewing, and deleting authentication
 * factors. Supports TOTP authenticators, SMS, Email, Push notifications, and recovery codes.
 *
 * @param props - {@link UserMFAManagementProps}
 * @param props.customMessages - Custom i18n message overrides
 * @param props.styling - CSS variables and class overrides
 * @param props.hideHeader - Hide the header section
 * @param props.showActiveOnly - Show only enrolled factors
 * @param props.disableEnroll - Disable enroll actions
 * @param props.disableDelete - Disable delete actions
 * @param props.readOnly - Render in read-only mode
 * @param props.factorConfig - Per-factor visibility/enabled configuration
 * @param props.enrollAction - Lifecycle hooks for enrollment; onBefore to cancel, onAfter on success
 * @param props.deleteAction - Lifecycle hooks for deletion; onBefore to cancel, onAfter on success
 * @param props.schema - Validation schema overrides
 * @returns MFA management component
 *
 * @see {@link UserMFAManagementProps} for full props documentation
 *
 * @example
 * ```tsx
 * <UserMFAManagement
 *   enrollAction={{ onAfter: (factor) => console.log('Enrolled:', factor) }}
 *   deleteAction={{ onAfter: (factor) => console.log('Deleted:', factor) }}
 *   factorConfig={{
 *     otp: { enabled: true },
 *     sms: { enabled: true },
 *     email: { enabled: false },
 *   }}
 * />
 * ```
 */
function UserMFAManagement({
  customMessages = {},
  styling = DEFAULT_STYLING,
  hideHeader = false,
  showActiveOnly = false,
  disableEnroll = false,
  disableDelete = false,
  readOnly = false,
  factorConfig = {},
  enrollAction,
  deleteAction,
  schema,
}: UserMFAManagementProps) {
  useTelemetry('user-mfa-management');
  const {
    factorsByType,
    isLoadingFactors,
    isEnrolling,
    isDeleting,
    isConfirming,
    isEnrollDialogOpen,
    enrollFactor,
    enrollmentPhase,
    contact,
    otpData,
    recoveryCode,
    isDeleteDialogOpen,
    factorToDelete,
    visibleFactorTypes,
    hasNoActiveFactors,
    handleEnroll,
    handleCloseEnrollDialog,
    handleDeleteFactor,
    handleConfirmDelete,
    handleCancelDelete,
    handleSendCode,
    handleResendCode,
    handleConfirmOtp,
    handleConfirmPush,
    handleConfirmRecoveryCode,
    handleEnterQRPhase,
  } = useUserMFA({
    showActiveOnly,
    readOnly,
    disableDelete,
    factorConfig,
    customMessages,
    enrollAction,
    deleteAction,
  });

  return (
    <GateKeeper styling={styling} isLoading={isLoadingFactors}>
      <UserMFAManagementView
        schema={schema}
        isEnrolling={isEnrolling}
        isDeleting={isDeleting}
        isConfirming={isConfirming}
        styling={styling}
        customMessages={customMessages}
        hideHeader={hideHeader}
        showActiveOnly={showActiveOnly}
        disableEnroll={disableEnroll}
        disableDelete={disableDelete}
        readOnly={readOnly}
        factorConfig={factorConfig}
        isEnrollDialogOpen={isEnrollDialogOpen}
        enrollFactor={enrollFactor}
        enrollmentPhase={enrollmentPhase}
        contact={contact}
        otpData={otpData}
        recoveryCode={recoveryCode}
        isDeleteDialogOpen={isDeleteDialogOpen}
        factorToDelete={factorToDelete}
        factorsByType={factorsByType}
        visibleFactorTypes={visibleFactorTypes}
        hasNoActiveFactors={hasNoActiveFactors}
        onEnrollFactor={handleEnroll}
        onDeleteFactor={handleDeleteFactor}
        onCloseEnrollDialog={handleCloseEnrollDialog}
        onConfirmDelete={handleConfirmDelete}
        onCancelDelete={handleCancelDelete}
        onSubmitContact={handleSendCode}
        onResendCode={handleResendCode}
        onConfirmOtp={handleConfirmOtp}
        onContinueQRScan={handleConfirmPush}
        onConfirmRecoveryCode={handleConfirmRecoveryCode}
        onStartQREnrollment={handleEnterQRPhase}
      />
    </GateKeeper>
  );
}

/**
 * UserMFAManagementView — Presentational component.
 * @param props - All state and handlers passed directly.
 * @returns User Management View element
 * @internal
 */
function UserMFAManagementView({
  schema,
  isEnrolling,
  isDeleting,
  isConfirming,
  styling,
  customMessages,
  hideHeader,
  showActiveOnly,
  disableEnroll,
  disableDelete,
  readOnly,
  factorConfig,
  isEnrollDialogOpen,
  enrollFactor,
  enrollmentPhase,
  contact,
  otpData,
  recoveryCode,
  isDeleteDialogOpen,
  factorToDelete,
  factorsByType,
  visibleFactorTypes,
  hasNoActiveFactors,
  onEnrollFactor,
  onDeleteFactor,
  onCloseEnrollDialog,
  onConfirmDelete,
  onCancelDelete,
  onSubmitContact,
  onResendCode,
  onConfirmOtp,
  onContinueQRScan,
  onConfirmRecoveryCode,
  onStartQREnrollment,
}: UserMFAManagementViewProps) {
  const { isDarkMode } = useTheme();
  const { t } = useTranslator('user_mfa_management', customMessages);
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  return (
    <StyledScope style={currentStyles.variables}>
      {!hideHeader && <Header title={t('header.title')} description={t('header.description')} />}

      {showActiveOnly && hasNoActiveFactors ? (
        <Card className={cn(currentStyles.classes?.['UserMFAManagement-item'])}>
          <MFAEmptyState message={t('no_active_mfa')} />
        </Card>
      ) : (
        <div className="flex flex-col gap-4 w-full">
          {visibleFactorTypes.map((factorType) => {
            const factors = factorsByType[factorType] || [];
            const activeFactors = factors.filter((f) => f.enrolled);
            const isEnabledFactor = factorConfig?.[factorType]?.enabled !== false;
            const hasActiveFactors = activeFactors.length > 0;

            return (
              <Card
                key={factorType}
                className={cn(
                  !isEnabledFactor && 'opacity-50 pointer-events-none',
                  currentStyles.classes?.['UserMFAManagement-item'],
                )}
                aria-disabled={!isEnabledFactor}
                aria-label={t(`factors.${factorType}.title`)}
              >
                <CardHeader>
                  <CardTitle className="flex flex-wrap items-center gap-2 sm:gap-3">
                    <span
                      className="break-words text-card-foreground whitespace-normal text-body font-medium"
                      id={`factor-title-${factorType}`}
                    >
                      {t(`factors.${factorType}.title`)}
                    </span>

                    {hasActiveFactors && (
                      <Badge
                        variant="success"
                        size="sm"
                        className="shrink-0"
                        aria-label={t('factors.meta.enabled')}
                      >
                        {t('factors.meta.enabled')}
                      </Badge>
                    )}
                  </CardTitle>

                  {!hasActiveFactors && (
                    <CardDescription
                      className="font-normal text-paragraph break-words"
                      id={`factor-desc-${factorType}`}
                    >
                      {t(`factors.${factorType}.description`)}
                    </CardDescription>
                  )}

                  {!readOnly && (
                    <CardAction>
                      <Button
                        size="default"
                        variant="outline"
                        className="text-sm w-full sm:w-auto shrink-0"
                        onClick={() => onEnrollFactor(factorType)}
                        disabled={disableEnroll || !isEnabledFactor}
                        aria-label={t(`factors.${factorType}.button_text`)}
                        aria-describedby={`factor-title-${factorType}`}
                      >
                        {t(`factors.${factorType}.button_text`)}
                      </Button>
                    </CardAction>
                  )}
                </CardHeader>

                {hasActiveFactors && (
                  <CardContent>
                    <FactorsList
                      factors={activeFactors}
                      factorType={factorType}
                      readOnly={readOnly}
                      isEnabledFactor={isEnabledFactor}
                      onDeleteFactor={onDeleteFactor}
                      isDeletingFactor={isDeleting}
                      disableDelete={disableDelete}
                      styling={styling}
                      customMessages={customMessages}
                    />
                  </CardContent>
                )}
              </Card>
            );
          })}
        </div>
      )}
      {enrollFactor && (
        <EnrollFactorModal
          open={isEnrollDialogOpen}
          onClose={onCloseEnrollDialog}
          factorType={enrollFactor}
          enrollmentPhase={enrollmentPhase}
          contact={contact}
          otpData={otpData}
          recoveryCode={recoveryCode}
          isEnrolling={isEnrolling}
          isConfirming={isConfirming}
          onSubmitContact={onSubmitContact}
          onResendCode={onResendCode}
          onConfirmOtp={onConfirmOtp}
          onContinueQRScan={onContinueQRScan}
          onConfirmRecoveryCode={onConfirmRecoveryCode}
          onStartQREnrollment={onStartQREnrollment}
          schema={schema}
          styling={styling}
          customMessages={customMessages}
        />
      )}
      <FactorDeleteModal
        open={isDeleteDialogOpen}
        onOpenChange={(open) => !open && onCancelDelete()}
        factorToDelete={factorToDelete}
        isDeletingFactor={isDeleting}
        onConfirm={onConfirmDelete}
        onCancel={onCancelDelete}
        styling={styling}
        customMessages={customMessages}
      />
    </StyledScope>
  );
}

export { UserMFAManagement, UserMFAManagementView };

/**
 * MFA factor deletion modal.
 * @module factor-delete-modal
 * @internal
 */

import { getComponentStyles } from '@auth0/universal-components-core';
import * as React from 'react';

import { Button } from '@/components/ui/button';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Separator } from '@/components/ui/separator';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { cn } from '@/lib/utils';
import type { FactorDeleteModalProps } from '@/types/my-account/user-mfa-management/factor-delete-modal-types';

/**
 *
 * @param props - Component props.
 * @param props.open - Whether the component is open/visible
 * @param props.onOpenChange - Callback fired when open state changes
 * @param props.factorToDelete - The factor selected for deletion
 * @param props.isDeletingFactor - Whether a factor deletion is in progress
 * @param props.onConfirm - Callback fired when the action is confirmed
 * @param props.onCancel - Callback fired when the operation is cancelled
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.customMessages - Custom translation messages to override defaults
 * @returns JSX element
 */
export function FactorDeleteModal({
  open,
  onOpenChange,
  factorToDelete,
  isDeletingFactor,
  onConfirm,
  onCancel,
  styling = {
    variables: {
      common: {},
      light: {},
      dark: {},
    },
    classes: {},
  },
  customMessages = {},
}: FactorDeleteModalProps) {
  const { t } = useTranslator('user_mfa_management', customMessages);
  const { isDarkMode } = useTheme();
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        style={currentStyles?.variables}
        className={cn(
          'w-[600px] min-h-44 max-h-[90vh] gap-4',
          currentStyles.classes?.['FactorDeleteModal-dialogContent'],
        )}
      >
        <DialogHeader>
          <DialogTitle className="text-left text-title font-medium">
            {t('remove_factor_dialog.title')}
          </DialogTitle>
          <DialogDescription className="sr-only">
            {t('remove_factor_dialog.title')}
          </DialogDescription>
        </DialogHeader>
        <Separator />
        <p className="text-center text-paragraph font-normal text-primary">
          {factorToDelete?.type && t(`remove_factor_dialog.consent.${factorToDelete.type}`)}
        </p>

        <DialogFooter className="mt-6">
          <Button
            variant="outline"
            size="default"
            className="text-sm"
            onClick={onCancel}
            disabled={isDeletingFactor}
            aria-label={t('actions.cancel_button_label')}
          >
            {t('actions.cancel_button_label')}
          </Button>
          <Button
            variant="destructive"
            size="default"
            className="text-sm"
            onClick={() => void onConfirm()}
            disabled={isDeletingFactor}
            aria-label={t('actions.confirm_button_label')}
          >
            {isDeletingFactor
              ? t('actions.deleting_button_text')
              : t('actions.confirm_button_label')}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

/**
 * MFA contact input form for email/SMS enrollment.
 * @module contact-input-form
 * @internal
 */

import {
  FACTOR_TYPE_EMAIL,
  createEmailContactSchema,
  createSmsContactSchema,
  type EmailContactForm,
  type SmsContactForm,
  getComponentStyles,
} from '@auth0/universal-components-core';
import { zodResolver } from '@hookform/resolvers/zod';
import { MailIcon, SmartphoneIcon } from 'lucide-react';
import * as React from 'react';
import { useForm } from 'react-hook-form';

import { OTPVerificationForm } from './otp-verification-form';

import { Button } from '@/components/ui/button';
import { DialogFooter } from '@/components/ui/dialog';
import {
  Form,
  FormField,
  FormItem,
  FormLabel,
  FormControl,
  FormMessage,
  FormDescription,
} from '@/components/ui/form';
import { Spinner } from '@/components/ui/spinner';
import { TextField } from '@/components/ui/text-field';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { FORM_REVALIDATE_MODE, FORM_VALIDATION_MODE } from '@/lib/constants/form-constants';
import {
  ENTER_CONTACT,
  ENTER_OTP,
} from '@/lib/constants/my-account/user-mfa-management/user-mfa-constants';
import type { ContactInputFormProps } from '@/types/my-account/user-mfa-management/factor-enrollment-types';

type ContactForm = EmailContactForm | SmsContactForm;

/**
 * Contact input form for email/SMS MFA enrollment.
 * @param props - Component props.
 * @param props.factorType - The MFA factor type
 * @param props.contact - Current contact value (email or phone) from hook state
 * @param props.phase - Current contact enrollment phase (enterContact or enterOtp)
 * @param props.isEnrolling - Whether enrollment is in progress
 * @param props.isConfirming - Whether OTP confirmation is in progress
 * @param props.onSubmitContact - Called with contact options; returns true on success
 * @param props.onResendCode - Called to resend the OTP code
 * @param props.onConfirmOtp - Called with the 6-digit OTP code
 * @param props.onClose - Callback fired when the component should close
 * @param props.onPhaseChange - Callback to advance or rewind the contact phase
 * @param props.schema - Zod validation schema
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.customMessages - Custom translation messages to override defaults
 * @returns JSX element
 */
export function ContactInputForm({
  factorType,
  contact,
  phase,
  isEnrolling,
  isConfirming,
  onSubmitContact,
  onResendCode,
  onConfirmOtp,
  onClose,
  onPhaseChange,
  schema,
  styling = {
    variables: {
      common: {},
      light: {},
      dark: {},
    },
    classes: {},
  },
  customMessages = {},
}: ContactInputFormProps) {
  const { t } = useTranslator('user_mfa_management', customMessages);
  const { isDarkMode } = useTheme();
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const ContactSchema = React.useMemo(() => {
    return factorType === FACTOR_TYPE_EMAIL
      ? createEmailContactSchema(t('enrollment.email.invalid'), schema?.email)
      : createSmsContactSchema(t('enrollment.phone.invalid'), schema?.phone);
  }, [factorType, t, schema]);

  const form = useForm<ContactForm>({
    resolver: zodResolver(ContactSchema),
    mode: FORM_VALIDATION_MODE,
    reValidateMode: FORM_REVALIDATE_MODE,
    defaultValues: { contact: contact || '' },
  });

  const handleCancel = () => {
    form.reset();
    onClose();
  };

  const handleBack = () => onPhaseChange(ENTER_CONTACT);

  const handleSubmit = async (data: ContactForm) => {
    const options: Record<string, string> =
      factorType === FACTOR_TYPE_EMAIL ? { email: data.contact } : { phone_number: data.contact };
    const success = await onSubmitContact(options);
    if (success) onPhaseChange(ENTER_OTP);
  };

  if (phase !== ENTER_CONTACT) {
    return (
      <OTPVerificationForm
        factorType={factorType}
        contact={contact}
        isConfirming={isConfirming}
        isEnrolling={isEnrolling}
        onConfirmOtp={onConfirmOtp}
        onBack={handleBack}
        onResend={onResendCode}
        styling={styling}
        customMessages={customMessages}
      />
    );
  }

  return (
    <div style={currentStyles.variables} className="w-full">
      <div className="flex flex-col items-center justify-center flex-1 space-y-10">
        {isEnrolling ? (
          <div className="flex items-center justify-center w-full" role="status" aria-live="polite">
            <Spinner aria-label={t('loading_text')} />
          </div>
        ) : (
          <div className="w-full">
            <Form {...form}>
              <form
                onSubmit={form.handleSubmit(handleSubmit)}
                className="space-y-6"
                aria-describedby="contact-description"
              >
                <FormField
                  control={form.control}
                  name="contact"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel
                        className="text-left text-paragraph font-medium"
                        htmlFor="contact-input"
                      >
                        {factorType === FACTOR_TYPE_EMAIL
                          ? t('enrollment.email.label')
                          : t('enrollment.phone.label')}
                      </FormLabel>
                      <FormControl>
                        <TextField
                          id="contact-input"
                          type={factorType === FACTOR_TYPE_EMAIL ? 'email' : 'tel'}
                          autoComplete={factorType === FACTOR_TYPE_EMAIL ? 'email' : 'tel'}
                          startAdornment={
                            <div className="p-1.5" aria-hidden="true">
                              {factorType === FACTOR_TYPE_EMAIL ? <MailIcon /> : <SmartphoneIcon />}
                            </div>
                          }
                          placeholder={
                            factorType === FACTOR_TYPE_EMAIL
                              ? t('enrollment.email.placeholder')
                              : t('enrollment.phone.placeholder')
                          }
                          error={Boolean(form.formState.errors.contact)}
                          aria-invalid={Boolean(form.formState.errors.contact)}
                          {...field}
                        />
                      </FormControl>
                      <FormDescription className="text-paragraph font-normal text-left">
                        {factorType === FACTOR_TYPE_EMAIL
                          ? t('enrollment.email.description')
                          : t('enrollment.phone.description')}
                      </FormDescription>
                      <FormMessage
                        className="text-left text-paragraph"
                        id="contact-error"
                        role="alert"
                      />
                    </FormItem>
                  )}
                />
                <DialogFooter>
                  <Button
                    type="button"
                    className="text-sm"
                    variant="outline"
                    size="default"
                    onClick={handleCancel}
                  >
                    {t('actions.cancel_button_label')}
                  </Button>
                  <Button
                    type="submit"
                    size="default"
                    className="text-sm"
                    disabled={!form.formState.isValid || isEnrolling}
                  >
                    {t('actions.submit_button_label')}
                  </Button>
                </DialogFooter>
              </form>
            </Form>
          </div>
        )}
      </div>
    </div>
  );
}

/**
 * MFA factor enrollment modal.
 * @module enroll-factor-modal
 * @internal
 */

import { getComponentStyles } from '@auth0/universal-components-core';
import {
  FACTOR_TYPE_EMAIL,
  FACTOR_TYPE_PHONE,
  FACTOR_TYPE_RECOVERY_CODE,
} from '@auth0/universal-components-core';
import type { MFAType } from '@auth0/universal-components-core';
import * as React from 'react';

import { ContactInputForm } from './contact-input-form';
import { QRCodeEnrollmentForm } from './qr-code-enrollment-form';
import { ShowRecoveryCode } from './show-recovery-code';

import AppleLogo from '@/assets/icons/apple-logo';
import GoogleLogo from '@/assets/icons/google-logo';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Separator } from '@/components/ui/separator';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import {
  ENTER_QR,
  ENTER_CONTACT,
  ENTER_OTP,
  QR_PHASE_INSTALLATION,
  QR_PHASE_ENTER_OTP,
  QR_PHASE_SCAN,
  SHOW_RECOVERY_CODE,
  GUARDIAN_APP_STORE_URL,
  GUARDIAN_PLAY_STORE_URL,
} from '@/lib/constants/my-account/user-mfa-management/user-mfa-constants';
import { cn } from '@/lib/utils';
import type {
  ContactPhase,
  QRPhase,
  EnrollFactorModalProps,
  InstallationPhaseProps,
} from '@/types/my-account/user-mfa-management/factor-enrollment-types';

const DEFAULT_STYLING: EnrollFactorModalProps['styling'] = {
  variables: { common: {}, light: {}, dark: {} },
  classes: {},
};

const ENROLL_TITLE_KEYS: Partial<Record<MFAType, string>> = {
  [FACTOR_TYPE_PHONE]: 'enrollment.phone.title',
  [FACTOR_TYPE_EMAIL]: 'enrollment.email.title',
  [FACTOR_TYPE_RECOVERY_CODE]: 'enrollment.recovery_code.title',
};

const VERIFY_TITLE_KEYS: Partial<Record<MFAType, string>> = {
  [FACTOR_TYPE_PHONE]: 'enrollment.verify.phone.title',
  [FACTOR_TYPE_EMAIL]: 'enrollment.verify.email.title',
};

/**
 * @param factorType - The MFA factor type being enrolled
 * @param qrPhase - Current QR enrollment phase
 * @param contactPhase - Current contact enrollment phase
 * @returns Translation key for the enrollment dialog title
 */
function getEnrollTitleKey(
  factorType: MFAType | null,
  qrPhase: QRPhase,
  contactPhase: ContactPhase,
): string {
  if (qrPhase === QR_PHASE_ENTER_OTP || contactPhase === ENTER_OTP) {
    return (factorType && VERIFY_TITLE_KEYS[factorType]) ?? 'enrollment.verify.totp.title';
  }
  return (factorType && ENROLL_TITLE_KEYS[factorType]) ?? 'enrollment.push.install_title';
}

/**
 * @param props - Component props
 * @param props.onClose - Called when the user cancels
 * @param props.onStartQREnrollment - Called when the user continues to QR scan
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.customMessages - Custom translation messages to override defaults
 * @returns Installation phase UI with app store links and continue button
 */
function InstallationPhase(props: InstallationPhaseProps) {
  const { onClose, onStartQREnrollment, styling = DEFAULT_STYLING, customMessages = {} } = props;
  const { t } = useTranslator('user_mfa_management', customMessages);
  const { isDarkMode } = useTheme();
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );
  return (
    <div style={currentStyles.variables} className="w-full">
      <div className="flex flex-col items-stretch flex-1 space-y-10">
