/**
 * MFA enrollment dialog — renders the correct form for each enrollment phase.
 * @param props - Component props
 * @param props.open - Whether the dialog is open
 * @param props.onClose - Called when the dialog should close
 * @param props.factorType - The MFA factor type being enrolled
 * @param props.enrollmentPhase - Current enrollment phase
 * @param props.contact - Contact value (email or phone) for contact-based factors
 * @param props.otpData - QR barcode URI and manual input code for QR-based factors
 * @param props.recoveryCode - Recovery code for recovery-code factor
 * @param props.isEnrolling - Whether enrollment is in progress
 * @param props.isConfirming - Whether OTP confirmation is in progress
 * @param props.onSubmitContact - Called with contact options to initiate enrollment
 * @param props.onResendCode - Called to resend the verification code
 * @param props.onConfirmOtp - Called with the OTP code to complete enrollment
 * @param props.onContinueQRScan - Called when the user confirms the QR scan step
 * @param props.onConfirmRecoveryCode - Called when the user confirms the recovery code
 * @param props.onStartQREnrollment - Called to initiate the QR enrollment API call
 * @param props.schema - Validation schema overrides
 * @param props.styling - Custom styling configuration
 * @param props.customMessages - Custom translation message overrides
 * @returns MFA enrollment dialog element
 */
export function EnrollFactorModal(props: EnrollFactorModalProps) {
  const {
    open,
    onClose,
    factorType,
    enrollmentPhase,
    contact,
    otpData,
    recoveryCode,
    isEnrolling,
    isConfirming,
    onSubmitContact,
    onResendCode,
    onConfirmOtp,
    onContinueQRScan,
    onConfirmRecoveryCode,
    onStartQREnrollment,
    schema,
    styling = DEFAULT_STYLING,
    customMessages = {},
  } = props;
  const { t } = useTranslator('user_mfa_management', customMessages);
  const { isDarkMode } = useTheme();
  const [qrPhase, setQrPhase] = React.useState<QRPhase>(QR_PHASE_SCAN);
  const [contactPhase, setContactPhase] = React.useState<ContactPhase>(ENTER_CONTACT);

  React.useEffect(() => {
    if (!open) return;
    setQrPhase(QR_PHASE_SCAN);
    setContactPhase(ENTER_CONTACT);
  }, [open, enrollmentPhase]);

  const enrollTitle = t(getEnrollTitleKey(factorType, qrPhase, contactPhase));

  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const renderPhase = () => {
    switch (enrollmentPhase) {
      case QR_PHASE_INSTALLATION:
        return (
          <InstallationPhase
            onClose={onClose}
            onStartQREnrollment={onStartQREnrollment}
            styling={styling}
            customMessages={customMessages}
          />
        );
      case ENTER_CONTACT:
        return (
          <ContactInputForm
            factorType={factorType}
            contact={contact}
            phase={contactPhase}
            isEnrolling={isEnrolling}
            isConfirming={isConfirming}
            onSubmitContact={onSubmitContact}
            onResendCode={onResendCode}
            onConfirmOtp={onConfirmOtp}
            onClose={onClose}
            onPhaseChange={setContactPhase}
            schema={schema}
            styling={styling}
            customMessages={customMessages}
          />
        );
      case ENTER_QR:
        return (
          <QRCodeEnrollmentForm
            factorType={factorType}
            otpData={otpData}
            isEnrolling={isEnrolling}
            isConfirming={isConfirming}
            phase={qrPhase}
            onContinueQRScan={onContinueQRScan}
            onConfirmOtp={onConfirmOtp}
            onClose={onClose}
            onPhaseChange={setQrPhase}
            styling={styling}
            customMessages={customMessages}
          />
        );
      case SHOW_RECOVERY_CODE:
        return (
          <ShowRecoveryCode
            recoveryCode={recoveryCode}
            isLoading={isEnrolling || isConfirming}
            onConfirmRecoveryCode={onConfirmRecoveryCode}
            onClose={onClose}
            styling={styling}
            customMessages={customMessages}
          />
        );
      default:
        return null;
    }
  };

  return (
    <Dialog open={open && Boolean(enrollmentPhase)} onOpenChange={onClose}>
      <DialogContent
        style={currentStyles.variables}
        className={cn(
          'w-[600px] min-h-44 max-h-[90vh] gap-4',
          currentStyles.classes?.['EnrollFactorModal-dialogContent'],
        )}
      >
        <DialogHeader>
          <DialogTitle className="text-left font-medium text-title">{enrollTitle}</DialogTitle>
          <DialogDescription className="sr-only">{enrollTitle}</DialogDescription>
        </DialogHeader>
        <Separator />
        {renderPhase()}
      </DialogContent>
    </Dialog>
  );
}

/**
 * OTP verification input form.
 * @module otp-verification-form
 * @internal
 */

import {
  type MFAType,
  FACTOR_TYPE_EMAIL,
  FACTOR_TYPE_TOTP,
  FACTOR_TYPE_PUSH_NOTIFICATION,
  getComponentStyles,
} from '@auth0/universal-components-core';
import * as React from 'react';
import { useForm } from 'react-hook-form';

import { Button } from '@/components/ui/button';
import { DialogFooter } from '@/components/ui/dialog';
import {
  Form,
  FormField,
  FormItem,
  FormControl,
  FormLabel,
  FormMessage,
} from '@/components/ui/form';
import { OTPField } from '@/components/ui/otp-field';
import { useTheme } from '@/hooks/shared/use-theme';
import { useTranslator } from '@/hooks/shared/use-translator';
import { FORM_VALIDATION_MODE } from '@/lib/constants/form-constants';
import type { OTPVerificationFormProps } from '@/types/my-account/user-mfa-management/factor-enrollment-types';

type OtpForm = {
  userOtp: string;
};

const maskContact = (contact: string, factorType: MFAType): string => {
  if (!contact) return '';

  if (factorType === FACTOR_TYPE_EMAIL) {
    const [local, domain] = contact.split('@');
    if (!domain || !local || local.length <= 2) return contact;
    return `${local.slice(0, 2)}${'*'.repeat(local.length - 2)}@${domain}`;
  }

  return contact.length > 6
    ? `${contact.slice(0, 3)}${'*'.repeat(contact.length - 6)}${contact.slice(-3)}`
    : contact;
};

/**
 * OTP verification form for MFA enrollment confirmation.
 * @param props - Component props.
 * @param props.factorType - The MFA factor type
 * @param props.contact - Contact information (email/phone)
 * @param props.isConfirming - Whether confirmation is in progress
 * @param props.onConfirmOtp - Called with the 6-digit OTP code on submit
 * @param props.onBack - Callback fired when back navigation is triggered
 * @param props.styling - Custom styling configuration with variables and classes
 * @param props.customMessages - Custom translation messages to override defaults
 * @returns JSX element
 */
export function OTPVerificationForm({
  factorType,
  contact,
  isConfirming,
  isEnrolling = false,
  onConfirmOtp,
  onBack,
  onResend,
  styling = {
    variables: { common: {}, light: {}, dark: {} },
    classes: {},
  },
  customMessages = {},
}: OTPVerificationFormProps) {
  const { t } = useTranslator('user_mfa_management', customMessages);
  const { isDarkMode } = useTheme();
  const currentStyles = React.useMemo(
    () => getComponentStyles(styling, isDarkMode),
    [styling, isDarkMode],
  );

  const form = useForm<OtpForm>({ mode: FORM_VALIDATION_MODE });
  const userOtp = form.watch('userOtp');

  const otpInputRef = React.useRef<HTMLInputElement>(null);

  React.useEffect(() => {
    otpInputRef.current?.focus();
  }, []);

  const maskedContact = contact ? maskContact(contact, factorType) : '';

  return (
    <div style={currentStyles.variables} className="w-full">
      <Form {...form}>
        <form
          onSubmit={form.handleSubmit((data) => onConfirmOtp(data.userOtp))}
          autoComplete="off"
          className="space-y-6"
          aria-describedby="otp-description"
        >
          <p
            id="otp-description"
            className="text-primary font-normal text-center break-words text-paragraph"
          >
            {[FACTOR_TYPE_PUSH_NOTIFICATION, FACTOR_TYPE_TOTP].includes(factorType)
              ? t('enrollment.verify.totp.description')
              : factorType === FACTOR_TYPE_EMAIL
                ? t('enrollment.verify.email.description', { name: maskedContact })
                : t('enrollment.verify.phone.description', { name: maskedContact })}
          </p>

          <FormField
            control={form.control}
            name="userOtp"
            render={({ field }) => (
              <FormItem>
                <FormLabel className="sr-only" htmlFor="otp-input">
                  {t('enrollment_form.show_otp.one_time_passcode')}
                </FormLabel>
                <FormControl>
                  <OTPField
                    id="otp-input"
                    length={6}
                    separator={{ character: '-', afterEvery: 3 }}
                    onChange={field.onChange}
                    inputRef={otpInputRef}
                    aria-invalid={!!form.formState.errors.userOtp}
                    value={field.value || ''}
                  />
                </FormControl>
                <FormMessage className="text-left text-paragraph" id="otp-error" role="alert" />
              </FormItem>
            )}
          />

          {onResend && (
            <p className="text-sm text-muted-foreground text-center">
              {t('enrollment.verify.resend_prompt')}
              <Button
                type="button"
                variant="link"
                className="text-sm ms-1 h-auto p-0"
                onClick={onResend}
                disabled={isEnrolling}
              >
                {t('enrollment.verify.resend')}
              </Button>
            </p>
          )}

          <DialogFooter>
            <Button
              type="button"
              className="text-sm"
              variant="outline"
              size="default"
              onClick={onBack}
            >
              {t('actions.back_button_label')}
            </Button>

            <Button
              type="submit"
              className="text-sm"
              size="default"
              disabled={userOtp?.length !== 6 || isConfirming}
              aria-label={
                isConfirming
                  ? t('enrollment.verify.verifying_text')
                  : t('actions.verify_button_label')
              }
            >
              {isConfirming
                ? t('enrollment.verify.verifying_text')
                : t('actions.verify_button_label')}
            </Button>
          </DialogFooter>
        </form>
      </Form>
    </div>
  );
}

