  QR_PHASE_ENTER_OTP,
  QR_PHASE_SCAN,
  GUARDIAN_APP_STORE_URL,
  GUARDIAN_PLAY_STORE_URL,
} from '@/lib/constants/my-account/user-mfa-management/user-mfa-constants';
