  factorType,
  readOnly,
  isEnabledFactor,
  onDeleteFactor,
  isDeletingFactor,
  disableDelete,
  styling = {
    variables: {
      common: {},
      light: {},
      dark: {},
    },
    classes: {},
  },
  customMessages = {},
}: FactorsListProps) {
  const { t, currentLanguage } = useTranslator('user_mfa_management', customMessages);
  const { isDarkMode } = useTheme();
  const IconComponent = FACTOR_ICONS[factorType as keyof typeof FACTOR_ICONS];

